DELETE FROM questions WHERE topic = 'The Endocrine System' AND subtopic IN ('Endocrine Pancreas', 'Gonads, Pineal & Other Tissues');

-- Q1 [Endocrine Pancreas] easy skill1 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'Within a pancreatic islet, one cell type releases a peptide that dampens the secretion of both blood-glucose-raising and blood-glucose-lowering signals from its neighboring islet cells. Which product does this cell type secrete?', '[{"label": "A", "text": "Somatostatin"}, {"label": "B", "text": "Insulin"}, {"label": "C", "text": "Glucagon"}, {"label": "D", "text": "Pancreatic polypeptide"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the delta cells of the pancreatic islets secrete somatostatin, a peptide that acts locally to inhibit the release of both glucagon (the blood-glucose-raising signal) and insulin (the blood-glucose-lowering signal) from neighboring islet cells; the described cell, whose product suppresses both of these hormones, is therefore the somatostatin-secreting delta cell. (Choice A) is correct: pancreatic somatostatin, produced by delta cells, is an inhibiting hormone that suppresses the secretion of both glucagon and insulin, matching the dual-inhibition role in the scenario. (Choice B) is incorrect: insulin is the beta-cell hormone that lowers blood glucose by increasing cellular glucose uptake and glycogen synthesis, so it is one of the signals being dampened rather than the dampening agent. (Choice C) is incorrect: glucagon is the alpha-cell hormone that raises blood glucose by stimulating glycogen breakdown and gluconeogenesis, so it is likewise one of the targets of inhibition, not the inhibitor. (Choice D) is incorrect: pancreatic polypeptide, secreted by PP cells of the islet, influences digestive and appetite functions but is not the peptide that broadly inhibits both islet glucose hormones. On a Skill 1 basis, this item requires recalling and identifying that the islet cell whose secretion inhibits both insulin and glucagon is the somatostatin-producing delta cell.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 45, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses a hormone that is a target of inhibition with the inhibitor itself' FROM q
  UNION ALL
  SELECT id, 'C', 'reversed_relationship', 'Confuses a hormone that is a target of inhibition with the inhibitor itself' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Names another genuine pancreatic islet product that lacks the described dual-inhibition function' FROM q;

-- Q2 [Endocrine Pancreas] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'After an overnight fast, receptors in the pancreatic islets detect that blood glucose has fallen below its set point. In response, one islet cell type increases secretion of the hormone that signals the liver to carry out glycogenolysis and gluconeogenesis. Which islet cell type increases its secretion?', '[{"label": "A", "text": "Beta cells"}, {"label": "B", "text": "Alpha cells"}, {"label": "C", "text": "Delta cells"}, {"label": "D", "text": "PP cells"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because the hormone that signals the liver to perform glycogenolysis and gluconeogenesis during a fast is glucagon, and glucagon is secreted by the alpha cells of the pancreatic islets; falling blood glucose stimulates these cells to release glucagon, which drives hepatic glucose output and returns blood glucose toward the set point. (Choice B) is correct: alpha cells secrete glucagon, the counter-regulatory hormone whose release is stimulated by low blood glucose and which triggers the liver to release glucose. (Choice A) is incorrect: beta cells secrete insulin, whose release is stimulated by elevated (not low) blood glucose and which lowers blood glucose by promoting cellular uptake and glycogen storage; insulin does not drive hepatic glucose output. (Choice C) is incorrect: delta cells secrete somatostatin, which inhibits the release of both insulin and glucagon; it does not itself signal the liver to release glucose. (Choice D) is incorrect: PP cells secrete pancreatic polypeptide, which has a role in appetite regulation and in modulating pancreatic secretions, not in signaling hepatic glycogenolysis or gluconeogenesis. This item requires applying knowledge of pancreatic islet cell function to identify the cell type responsible for the fasting glucose-raising response (Skill 2).', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Selects the islet cell whose hormone lowers rather than raises blood glucose, confusing the fasting response with the fed-state response' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Selects a real islet cell that modulates other islet hormones but does not directly signal hepatic glucose release' FROM q
  UNION ALL
  SELECT id, 'D', 'adjacent_fact', 'Selects a genuine islet cell type whose product is appetite-related rather than involved in hepatic glucose output' FROM q;

-- Q3 [Endocrine Pancreas] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'Thirty minutes after a volunteer eats a bowl of white rice, blood sampling shows a sharp spike in circulating glucose. Which endocrine response would most directly return the volunteer''s blood glucose toward baseline?', '[{"label": "A", "text": "An adrenal steroid that promotes hepatic gluconeogenesis"}, {"label": "B", "text": "A pancreatic hormone that triggers hepatic glycogen breakdown"}, {"label": "C", "text": "A pancreatic hormone that promotes cellular glucose uptake"}, {"label": "D", "text": "A pancreatic hormone that suppresses all islet secretion"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because a rise in blood glucose after a carbohydrate meal is detected by the pancreatic islet cells that secrete insulin; insulin signals skeletal muscle, adipose, and liver cells to take up the excess glucose and stimulates the liver to convert that glucose into stored glycogen, both of which pull glucose out of the bloodstream and return it toward baseline. (Choice C) is correct: a pancreatic hormone that increases glucose transport into muscle and liver cells while promoting glycogen synthesis (insulin from the beta cells) is precisely the negative-feedback response to elevated post-meal glucose, lowering the circulating level. (Choice B) is incorrect: a pancreatic hormone that triggers hepatic glycogen breakdown (glucagon from the alpha cells) is released in response to LOW blood glucose and raises blood glucose, so it would worsen, not correct, the post-meal spike; it is the counter-regulatory opposite of the needed response. (Choice A) is incorrect: an adrenal steroid promoting hepatic gluconeogenesis (cortisol from the adrenal cortex) also increases blood glucose and is released during stress rather than as the primary response to a meal, so it moves glucose in the wrong direction. (Choice D) is incorrect: a pancreatic hormone that suppresses islet secretion (somatostatin from the delta cells) inhibits the release of both insulin and glucagon; blocking secretion would prevent the very insulin response that lowers glucose, so it does not directly return glucose toward baseline. Applying the concept, the scenario requires predicting that elevated glucose evokes the hormone driving cellular uptake and glycogen storage, tracing the perturbation to the specific islet cell and its glucose-lowering effect.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Selects the counter-regulatory pancreatic hormone (glucagon) that raises rather than lowers blood glucose' FROM q
  UNION ALL
  SELECT id, 'A', 'adjacent_fact', 'Chooses a real glucose-affecting hormone (cortisol) from the wrong gland acting in the wrong direction and context' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'Picks a genuine pancreatic islet hormone (somatostatin) but assigns it a function that would block, not produce, the needed response' FROM q;

-- Q4 [Endocrine Pancreas] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'During prolonged fasting in a healthy adult, a liver biopsy shows hepatocytes actively degrading stored glycogen, synthesizing new glucose from circulating amino acids, and exporting glucose into the hepatic vein. An elevated pancreatic islet-cell secretion is directly driving this hepatic activity. Which secretion is elevated?', '[{"label": "A", "text": "Insulin from the beta cells"}, {"label": "B", "text": "Cortisol from the adrenal cortex"}, {"label": "C", "text": "Somatostatin from the delta cells"}, {"label": "D", "text": "Glucagon from the alpha cells"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the observed hepatic activities—glycogenolysis (breaking glycogen back down to glucose), gluconeogenesis (building glucose from amino acids), and net glucose export into the blood—are precisely the liver responses evoked by glucagon, which the alpha cells of the pancreatic islets secrete when blood glucose falls, as during fasting; taken together these actions raise blood glucose back toward the normal range. (Choice D) is correct: glucagon is secreted by the alpha cells of the pancreatic islets in direct response to falling blood glucose, and it is the islet hormone that signals hepatocytes to run glycogenolysis and gluconeogenesis and to export glucose into the blood—exactly the biopsy pattern described—so an elevated glucagon level is what raises blood glucose during fasting. (Choice A) is incorrect: insulin is glucagon''s antagonist and drives the opposite direction—it promotes glucose uptake by muscle and adipose cells and stimulates the liver to convert glucose into glycogen while inhibiting glycogenolysis and gluconeogenesis, so elevated insulin would suppress, not produce, the biopsy''s glucose-liberating pattern. (Choice C) is incorrect: somatostatin, from the delta cells, is an inhibitory hormone that suppresses the release of both insulin and glucagon; it does not itself signal hepatocytes to break down glycogen or export glucose. (Choice B) is incorrect: although cortisol does promote gluconeogenesis and can raise blood glucose, it is a glucocorticoid secreted by the adrenal cortex, not a pancreatic islet-cell secretion, so it cannot be the elevated islet product driving this response. Skill 2 is exercised because the student must interpret the described hepatic data to infer the underlying low-glucose perturbation, then reason across the antagonistic insulin–glucagon pair to identify which islet hormone dominates and confirm the direction of glucose flux.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'antagonist_action' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'same_organ_inhibitory_hormone_mistaken_for_effector' FROM q
  UNION ALL
  SELECT id, 'B', 'partial_truth', 'correct_glucose_effect_wrong_gland' FROM q;

-- Q5 [Endocrine Pancreas] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A pancreatic islet tumor continuously oversecretes a peptide hormone that is normally released only by the islets'' smallest major hormone-producing cell population. As the tumor grows, what is the most likely direct effect on secretion of the pancreas''s two principal blood-glucose-regulating hormones?', '[{"label": "A", "text": "Insulin decreases while glucagon secretion rises"}, {"label": "B", "text": "Both insulin and glucagon secretion decrease"}, {"label": "C", "text": "Insulin rises while glucagon secretion decreases"}, {"label": "D", "text": "Both insulin and glucagon secretion increase"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because the smallest major hormone-producing population of the pancreatic islets is the delta cell (about 4 percent of islet cells), which secretes somatostatin, an inhibiting hormone that suppresses the release of both insulin and glucagon; a tumor chronically oversecreting this hormone therefore drives down secretion of both principal glucose-regulating hormones simultaneously. (Choice B) is correct: somatostatin from delta cells inhibits both beta-cell insulin release and alpha-cell glucagon release, so elevated somatostatin lowers both, matching the textbook description of pancreatic somatostatin as an inhibitor of both glucagon and insulin. (Choice A) is incorrect: it treats the perturbing hormone as a reciprocal glucose signal that pushes insulin and glucagon in opposite directions, but somatostatin does not raise glucagon; it inhibits glucagon release rather than stimulating the counter-regulatory alpha-cell response. (Choice C) is incorrect: it assumes the hormone potentiates insulin (as an incretin such as GIP or GLP-1 would) while suppressing glucagon, but somatostatin inhibits insulin secretion as well and is not an insulin-stimulating incretin. (Choice D) is incorrect: it assumes any additional islet paracrine peptide stimulates both endocrine outputs, whereas somatostatin is defined functionally as an inhibiting hormone that reduces, not increases, both insulin and glucagon release. Applying the delta-cell/somatostatin relationship to a novel tumor scenario requires using the concept rather than recalling a definition, so a student must reason that inhibition of both hormones follows from oversecretion of the minor islet peptide.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'A', 'reversed_relationship', 'Treats the inhibitory islet hormone as a reciprocal glucose signal that raises glucagon while lowering insulin' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Confuses the minor islet peptide with an incretin (GIP/GLP-1) that stimulates insulin and suppresses glucagon' FROM q
  UNION ALL
  SELECT id, 'D', 'misconception', 'Assumes any added islet paracrine peptide stimulates rather than inhibits both endocrine outputs' FROM q;

-- Q6 [Endocrine Pancreas] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'Shortly after a person finishes a carbohydrate-rich meal, their blood glucose rises sharply, and the pancreatic hormone that predominates in this setting drives skeletal muscle, adipose, and liver cells to respond. Which category of metabolic activity does this hormone most favor in those target tissues?', '[{"label": "A", "text": "Formation of glucose from amino acids"}, {"label": "B", "text": "Breakdown of hepatic glycogen into glucose"}, {"label": "C", "text": "Synthesis of glycogen and triglyceride stores"}, {"label": "D", "text": "Release of fatty acids from stored fat"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because a sharp post-meal rise in blood glucose is the signal that triggers insulin secretion from the beta cells of the pancreatic islets, and insulin''s dominant action is anabolic: it directs target cells to take up the excess glucose and convert it into storage forms, stimulating the liver to convert glucose into glycogen while promoting triglyceride and protein synthesis. These are building (anabolic) reactions that consume energy to assemble complex storage molecules from simpler precursors, which is exactly the category favored when fuel is abundant. (Choice C) is correct: glycogen synthesis (glycogenesis) and triglyceride synthesis are the storage-building processes insulin stimulates when glucose is plentiful, lowering blood glucose by moving it into stored forms. (Choice B) is incorrect: the breakdown of hepatic glycogen into glucose is glycogenolysis, a catabolic mobilizing process driven by glucagon (and epinephrine) when blood glucose is low, not by the hormone that dominates after a meal; insulin actually inhibits this process. (Choice A) is incorrect: forming glucose from amino acids is gluconeogenesis, a glucose-raising response stimulated by glucagon and cortisol during fasting, and insulin suppresses rather than favors it. (Choice D) is incorrect: releasing fatty acids from stored fat is lipolysis, a catabolic mobilization of energy reserves promoted by glucagon and cortisol during energy deficit, the opposite of the fat storage that the post-meal hormone favors. Answering requires the Skill 2 ability to take the given high-glucose scenario, identify the class of process a fuel-storing hormone would favor, and distinguish building (anabolic) reactions from the several plausible-sounding breakdown (catabolic) reactions.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 80, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'opposite-hormone-action (glycogenolysis is the catabolic action of glucagon, inhibited by insulin)' FROM q
  UNION ALL
  SELECT id, 'A', 'reversed_relationship', 'fasting-response confusion (gluconeogenesis is a glucose-raising, glucagon/cortisol-driven process, not a storage process)' FROM q
  UNION ALL
  SELECT id, 'D', 'process_step_confusion', 'lipolysis-vs-lipogenesis (fat mobilization confused with fat storage)' FROM q;

-- Q7 [Endocrine Pancreas] hard skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A 12-year-old presents with hyperglycemia, and blood tests reveal autoantibodies that have selectively destroyed one hormone-secreting cell population of the pancreatic islets, leaving the patient dependent on hormone injections. A physician wants to determine whether a second, unrelated adult patient''s hyperglycemia arises instead from impaired target-tissue responsiveness. Which laboratory finding in the adult would most strongly support that alternative mechanism?', '[{"label": "A", "text": "Reduced fasting serum somatostatin levels"}, {"label": "B", "text": "Undetectable fasting serum insulin despite persistent hyperglycemia"}, {"label": "C", "text": "Elevated fasting serum glucagon with hyperglycemia"}, {"label": "D", "text": "Elevated fasting serum insulin despite persistent hyperglycemia"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because target-tissue resistance means peripheral cells respond poorly to insulin even though the beta cells still produce it; the pancreas actually increases insulin secretion in compensation, so the hallmark of a resistance-driven mechanism is elevated (not deficient) fasting insulin persisting alongside high blood glucose. This directly contrasts with the child''s autoimmune destruction of the insulin-producing beta cells, which causes an absolute lack of the hormone. (Choice D) is correct: in insulin resistance the beta cells remain intact and hypersecrete insulin to overcome poor target-cell responsiveness, so measurable, even elevated, insulin coexists with hyperglycemia—evidence the defect lies downstream at the target tissue rather than in hormone supply. (Choice B) is incorrect: undetectable fasting insulin indicates an absolute deficiency of the hormone, which is exactly the child''s autoimmune beta-cell loss, not a target-tissue responsiveness problem. (Choice C) is incorrect: glucagon, secreted by the alpha cells, raises blood glucose by promoting glycogenolysis and gluconeogenesis, so elevated glucagon would implicate a counter-regulatory hormone excess rather than impaired insulin action at target tissues. (Choice A) is incorrect: somatostatin from the delta cells inhibits both insulin and glucagon release; reduced somatostatin does not describe reduced target-tissue responsiveness to insulin and is not a recognized cause of resistance-driven hyperglycemia. This item requires Skill 2 reasoning because the student must interpret laboratory data to infer an underlying mechanism and distinguish an absolute hormone-supply deficit from a downstream target-tissue defect.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses the absolute-deficiency profile of the described autoimmune (type 1) case with the resistance profile being asked about' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'Substitutes the counter-regulatory hormone glucagon (alpha cells) as if elevated glucagon defined insulin resistance' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'Treats a fall in the islet-inhibitory hormone somatostatin (delta cells) as a mechanism of target-tissue resistance' FROM q;

-- Q8 [Endocrine Pancreas] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A 52-year-old patient presents with persistent hyperglycemia. Lab work drawn in the fasting state shows a fasting plasma glucose well above normal, yet the patient''s serum insulin concentration is simultaneously elevated—markedly higher than that of a healthy fasting individual. Which finding best accounts for this combination?', '[{"label": "A", "text": "Skeletal muscle and adipose cells respond poorly to insulin"}, {"label": "B", "text": "Autoimmune destruction has eliminated the beta cells"}, {"label": "C", "text": "Alpha cells oversecrete glucagon during fasting"}, {"label": "D", "text": "The adrenal cortex overproduces cortisol"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the coexistence of high glucose AND high insulin can only be reconciled if the beta cells are actively secreting insulin but the target tissues fail to respond to it. Insulin''s principal targets—skeletal muscle and adipose cells—normally clear glucose from the blood when insulin binds its tyrosine-kinase receptor and mobilizes glucose-transporter vesicles to the membrane; when these cells are resistant, glucose stays elevated, the pancreas compensates by secreting even more insulin, and both values rise together. This is the defining lesion of type 2 diabetes: reduced sensitivity of tissue cells to insulin rather than a failure to produce it. (Choice A) is correct: target-cell (receptor-level) resistance leaves circulating insulin high while glucose uptake fails, exactly matching the paired high-insulin/high-glucose data. (Choice B) is incorrect: autoimmune loss of beta cells is type 1 diabetes, in which the beta cells produce no insulin—this predicts a LOW serum insulin, directly contradicting the elevated insulin measured here. (Choice C) is incorrect: excess glucagon from alpha cells would raise blood glucose, but glucagon does not cause a compensatory rise in insulin secretion sufficient to explain a markedly elevated fasting insulin, and it is not the primary defect underlying this classic presentation. (Choice D) is incorrect: cortisol excess (as in Cushing syndrome) can raise blood glucose, but the adrenal cortex is not the pancreatic source of insulin, and cortisol-driven hyperglycemia does not itself explain why measured insulin is high. To answer, a student must integrate two data points—high insulin excludes a production failure while high glucose signals unresolved insulin action—and infer a receptor-level defect rather than reading a definition, the reasoning characteristic of Skill 2.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'misconception', 'conflates type 2 with type 1 (no insulin produced)' FROM q
  UNION ALL
  SELECT id, 'C', 'adjacent_fact', 'correct pancreatic hyperglycemic hormone but wrong mechanism' FROM q
  UNION ALL
  SELECT id, 'D', 'partial_truth', 'real hyperglycemic hormone from wrong gland' FROM q;

-- Q9 [Endocrine Pancreas] medium skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A patient with untreated diabetes mellitus presents with a blood glucose of 320 mg/dL (normal ~90 mg/dL), urinating far more than 2.5 L per day, and reporting constant thirst. Which change in the nephron most directly explains the large urine volume?', '[{"label": "A", "text": "Reduced aldosterone lowers sodium and water reabsorption"}, {"label": "B", "text": "Too few aquaporin channels reach the collecting duct"}, {"label": "C", "text": "Filtered glucose surpasses tubular reabsorption, retaining water osmotically"}, {"label": "D", "text": "Absent insulin blocks tubular glucose reuptake"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because when blood glucose is far above normal, the amount of glucose filtered at the glomerulus exceeds the number of available sodium-glucose symporters in the proximal tubule; the excess glucose that cannot be reabsorbed remains in the tubular fluid, where its osmotic pull holds water in the filtrate and produces a high volume of urine (osmotic diuresis), which in turn drives the compensatory thirst. (Choice C) is correct: the tubular sodium-glucose transporters are saturated once filtered glucose exceeds their capacity, so unrecovered glucose stays in the lumen and acts as a powerful osmotic diuretic, drawing water into the urine and causing polyuria and polydipsia. (Choice B) is incorrect: a shortage of aquaporin channels in the collecting duct is the mechanism of diabetes insipidus (from insufficient ADH or ADH receptors), a distinct condition; here the driver is an osmotic solute load from glucose, not a failure to insert water channels. (Choice A) is incorrect: aldosterone governs sodium reabsorption, and reduced sodium reabsorption is not what occurs in hyperglycemia; the osmotically active solute overwhelming the tubules is glucose, not a sodium deficit. (Choice D) is incorrect: tubular glucose reabsorption occurs by sodium-glucose secondary active transport and does not depend on insulin; insulin lowers blood glucose by promoting cellular uptake elsewhere in the body, so its absence raises the filtered glucose load rather than directly blocking a reuptake step in the nephron. This item rewards Skill 2 reasoning by requiring the student to trace a causal chain from a quantitative sign (markedly elevated blood glucose) through transporter saturation to the osmotic mechanism producing the observed urinary and thirst symptoms, rather than recalling a definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'adjacent_fact', 'confusing diabetes mellitus polyuria with diabetes insipidus aquaporin/ADH mechanism' FROM q
  UNION ALL
  SELECT id, 'A', 'misconception', 'attributing osmotic water loss to a sodium/aldosterone deficit rather than a glucose solute load' FROM q
  UNION ALL
  SELECT id, 'D', 'reversed_relationship', 'assuming insulin controls renal glucose reabsorption, when tubular reuptake is insulin-independent sodium-glucose cotransport' FROM q;

-- Q10 [Endocrine Pancreas] easy skill1 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'After a carbohydrate-rich meal, a person''s blood glucose rises sharply and then, over the next hour, falls back toward baseline as skeletal muscle and liver cells increase their glucose uptake and convert the incoming glucose into glycogen for storage. Which hormone is chiefly responsible for driving this post-meal return of blood glucose toward baseline?', '[{"label": "A", "text": "The adrenal cortical glucocorticoid hormone"}, {"label": "B", "text": "The pancreatic alpha-cell hormone"}, {"label": "C", "text": "The adrenal medullary catecholamine hormone"}, {"label": "D", "text": "The pancreatic beta-cell hormone"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the hormone that promotes cellular glucose uptake and its storage as glycogen—thereby lowering elevated blood glucose after a meal—is insulin, which is secreted by the beta cells of the pancreatic islets. Rising blood glucose stimulates beta-cell secretion of this hormone, which signals skeletal muscle and liver cells to take up glucose and store it as glycogen, returning blood glucose toward baseline. (Choice D) is correct: the pancreatic beta-cell hormone (insulin) reduces blood glucose levels by facilitating glucose uptake into body cells and promoting glycogen storage, exactly the effect described. (Choice B) is incorrect: the pancreatic alpha-cell hormone (glucagon) is released in response to low blood glucose and raises blood glucose by stimulating glycogen breakdown, the opposite of the described fall. (Choice C) is incorrect: the adrenal medullary catecholamine (epinephrine) causes breakdown of glycogen into glucose, which would raise rather than lower blood glucose. (Choice A) is incorrect: the adrenal cortical glucocorticoid (cortisol) promotes catabolism of glycogen to glucose and generally elevates blood glucose, so it does not drive the post-meal decline. On skill: this question requires recognizing the source and glucose-lowering role of the hormone from a described physiological scenario, a foundational knowledge task.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 60, NULL)
  RETURNING id
)
INSERT INTO question_distractor_metadata (question_id, choice_label, distractor_category, archetype)
  SELECT id, 'B', 'reversed_relationship', 'Confuses the two pancreatic islet hormones and their opposite effects on blood glucose' FROM q
  UNION ALL
  SELECT id, 'C', 'misconception', 'Assumes any stress/metabolic hormone that mobilizes glucose helps regulate post-meal glucose' FROM q
  UNION ALL
