-- Q11 [Endocrine Pancreas] hard skill2 ans=A
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A patient accidentally self-administers a large overdose of a manufactured drug that mimics the islet hormone normally secreted in response to a rising blood glucose level after a meal. Thirty minutes later they become confused, sweaty, and tremulous. To reverse this emergency, the body must rapidly secrete which counter-regulatory hormone?', '[{"label": "A", "text": "Glucagon, from pancreatic alpha cells"}, {"label": "B", "text": "Insulin, from pancreatic beta cells"}, {"label": "C", "text": "Somatostatin, from pancreatic delta cells"}, {"label": "D", "text": "Epinephrine, from the adrenal cortex"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the drug mimics the beta-cell hormone insulin (the hormone released when a meal raises blood glucose), so an overdose drives blood glucose dangerously low; the confusion, sweating, and tremor are signs of the brain being starved of glucose (neuroglycopenia). Because the brain can use only glucose as an essential fuel, the body must reverse the low glucose by secreting insulin''s antagonist, glucagon, which is produced by the pancreatic alpha cells and raises blood glucose through hepatic glycogenolysis and gluconeogenesis. (Choice A) is correct: glucagon from alpha cells is the counter-regulatory hormone that opposes insulin and restores blood glucose after an overdose. (Choice B) is incorrect: insulin from beta cells is the very hormone the overdosed drug mimics; secreting more would deepen the hypoglycemia rather than reverse it, and this choice reflects the misconception that an insulin problem always means high blood glucose (true only for insulin deficiency, not insulin excess). (Choice C) is incorrect: somatostatin from delta cells inhibits the release of both insulin and glucagon and does not itself raise blood glucose, so it cannot correct hypoglycemia. (Choice D) is incorrect: epinephrine does help raise blood glucose during stress, but it is secreted by the adrenal medulla, not the adrenal cortex, so the stated source is wrong. As a Skill 2 problem, this requires integrating the direction of insulin''s effect, the consequence of hormone excess versus deficiency, and the antagonistic source that restores homeostasis, rather than recalling a single definition.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 95, NULL)
  RETURNING id
)
