-- Q12 [Endocrine Pancreas] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Endocrine Pancreas', 'A person has been fasting for 18 hours. Their blood glucose has dropped toward the lower end of the normal range, and a signaling molecule from the pancreas is now acting on hepatocytes to restore circulating glucose. Which pair of liver processes does this molecule activate to accomplish this?', '[{"label": "A", "text": "Glycogen breakdown and oxidation of glucose to generate ATP"}, {"label": "B", "text": "Glycogen breakdown and synthesis of new glucose from amino acids"}, {"label": "C", "text": "Glycogen synthesis and glucose oxidation"}, {"label": "D", "text": "Formation of ketone bodies for energy"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because during fasting the falling blood glucose stimulates the pancreatic alpha cells to release a hormone that acts on the liver to both break stored glycogen back into glucose (glycogenolysis) and build new glucose molecules from substrates such as amino acids and glycerol (gluconeogenesis); together these two processes raise circulating glucose. (Choice B) is correct: the fasting-state liver simultaneously runs glycogenolysis to liberate stored glucose and gluconeogenesis to manufacture additional glucose from amino acids and glycerol, which is exactly the combination needed to defend blood glucose once a meal has been digested and absorbed. (Choice A) is incorrect: glycogen breakdown is indeed a fasting action, but oxidizing that glucose for ATP would consume the very fuel the liver is trying to export, and hepatic glucose oxidation (glycolysis) is an insulin-driven, fed-state process, not a glucagon-driven fasting one; the fasting liver spares glucose for the brain and red blood cells and instead burns fatty acids for its own energy, so this pair is self-defeating. (Choice C) is incorrect: glycogen synthesis and glucose oxidation are fed-state, insulin-driven responses that consume or store glucose rather than release it, so they would drive blood glucose lower, the opposite of the required outcome. (Choice D) is incorrect: ketone body formation does occur during prolonged fasting, but ketones serve as an alternative fuel for tissues and are not glucose, so this process does not itself raise blood glucose. Skill 2: the question requires applying the relationship between the fasting stimulus and hepatic glucose output to predict which paired processes the signal must switch on, rather than recalling a labeled definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
