-- Q13 [Gonads, Pineal & Other Tissues] medium skill2 ans=D
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Gonads, Pineal & Other Tissues', 'A newborn with a 46,XY karyotype and internal testes shows external genitalia that resemble those of a female infant, and at the expected age of puberty fails to develop a deepened voice or increased body hair. A deficiency in the target-tissue action of which testis-derived hormone best accounts for this pattern?', '[{"label": "A", "text": "Melatonin from the pineal gland"}, {"label": "B", "text": "Inhibin from the sustentacular cells"}, {"label": "C", "text": "Estradiol converted in peripheral tissues"}, {"label": "D", "text": "The androgen from the interstitial cells"}]'::jsonb, 'D', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is D because the interstitial (Leydig) cells of the testes secrete an androgen that drives both the in-utero masculinization of the external genitalia and the emergence of male secondary sex characteristics at puberty; when target tissues cannot respond to this androgen, a genetically male (46,XY) infant with testes still develops female-appearing external genitalia and fails to virilize at puberty. (Choice D) is correct: the steroid androgen produced by Leydig cells (interstitial cells located between the seminiferous tubules) is the hormone whose action converts bipotential tissue into the glans penis in utero and later produces the deepened voice and body hair of puberty, so a defect in its tissue action produces exactly the described phenotype. (Choice B) is incorrect: inhibin is indeed a testicular product of the sustentacular (Sertoli) cells, but its function is to inhibit FSH release from the anterior pituitary; it plays no role in masculinizing the genitalia or in secondary sex characteristics, so its loss would not produce this developmental picture. (Choice C) is incorrect: estradiol is the principal estrogen and drives female secondary sex characteristics; although small amounts arise from peripheral conversion, a deficiency of estradiol action does not explain failed masculinization of a genetic male. (Choice A) is incorrect: melatonin is secreted by the pineal gland and regulates circadian rhythm and may modulate the timing of puberty via gonadotropins, but it is not a gonadal hormone and does not direct sexual differentiation or virilization. This item requires applying the source and developmental role of a specific gonadal hormone to a described phenotype rather than recalling a definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 90, NULL)
  RETURNING id
)
