WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Gonads, Pineal & Other Tissues', 'During puberty, a pediatric endocrinologist charts an adolescent whose rising pituitary gonadotropins are followed by breast tissue growth and a marked increase in subcutaneous adipose deposition. Which hormones, and from which gland, most directly produce these developmental changes?', '[{"label": "A", "text": "Estrogens and progesterone from the ovaries"}, {"label": "B", "text": "Androgens such as testosterone from the adrenal cortex"}, {"label": "C", "text": "Oxytocin released from the posterior pituitary"}, {"label": "D", "text": "Cortisol secreted from the adrenal cortex"}]'::jsonb, 'A', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is A because the female secondary sex characteristics described, including breast tissue development and increased adipose tissue, are driven by the steroid hormones estrogens and progesterone secreted by the ovaries once the ovarian follicles mature in response to the pituitary gonadotropins LH and FSH. (Choice A) is correct: estrogens are the primary ovarian hormones and, together with progesterone, stimulate the development of female secondary sex characteristics such as breast tissue and increased adipose tissue; both are steroids secreted by the ovaries in response to gonadotropin stimulation. (Choice B) is incorrect: androgens such as testosterone from the adrenal cortex are produced only in small amounts by the zona reticularis, and androgens drive male-pattern characteristics such as a deepened voice and increased muscle mass rather than breast and adipose development. (Choice C) is incorrect: oxytocin released from the posterior pituitary functions in uterine contraction during childbirth and the milk-ejection reflex, not in the pubertal development of secondary sex characteristics. (Choice D) is incorrect: cortisol secreted from the adrenal cortex is a glucocorticoid that raises blood glucose in the stress response and has no role in driving female reproductive development. This question requires reasoning from a described developmental effect back to the hormones and gland responsible, rather than recalling a stated definition.', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
