-- Q16 [Gonads, Pineal & Other Tissues] easy skill1 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Gonads, Pineal & Other Tissues', 'Volunteers kept in constant dim light develop weakened daily fluctuations in sleepiness, and their blood level of one hormone stops rising each evening—the rise that normally coincides with the onset of drowsiness. Which hormone shows this evening-linked pattern?', '[{"label": "A", "text": "Thyroxine"}, {"label": "B", "text": "Cortisol"}, {"label": "C", "text": "Melatonin"}, {"label": "D", "text": "Oxytocin"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because melatonin, secreted by the pinealocytes of the pineal gland, is released in a light-dependent pattern: as environmental light declines in the evening, melatonin synthesis increases, blood levels rise, and this rise causes drowsiness, whereas falling levels promote wakefulness. Under constant dim light, the normal dark-triggered evening surge is blunted, weakening the daily sleep-wake rhythm the hormone helps regulate. (Choice C) is correct: melatonin''s secretion tracks the light-dark cycle, rising in the evening to induce sleepiness and setting circadian timing. (Choice B) is incorrect: cortisol, a steroid hormone from the adrenal cortex, actually peaks in the early morning and mediates the stress response and metabolism rather than being triggered to rise by evening darkness to induce drowsiness. (Choice A) is incorrect: thyroxine, from the thyroid gland, regulates basal metabolic rate and overall energy expenditure and is not secreted in an evening, light-linked surge that produces sleepiness. (Choice D) is incorrect: oxytocin, released by the posterior pituitary, drives uterine contractions during childbirth and the milk let-down reflex, and has no role in generating the evening sleep signal. This is a Skill 1 item because it requires recognizing which hormone and gland are matched to a described physiological role in daily biological timing.', 'easy', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 1, 50, NULL)
  RETURNING id
)
