-- Q18 [Gonads, Pineal & Other Tissues] medium skill2 ans=B
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Gonads, Pineal & Other Tissues', 'A person relocates to a high-altitude city where the reduced partial pressure of oxygen chronically lowers the oxygen content of arterial blood. Over the following weeks, a hormone released in response to this hypoxic state produces an adaptive change in the blood. Which hormone is secreted, and what is its principal effect?', '[{"label": "A", "text": "A liver hormone that raises red blood cell production"}, {"label": "B", "text": "A kidney hormone that raises red blood cell production"}, {"label": "C", "text": "An adrenal hormone that raises sodium reabsorption"}, {"label": "D", "text": "A thyroid hormone that raises metabolic rate"}]'::jsonb, 'B', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is B because low blood oxygen is the specific trigger for erythropoietin (EPO), a hormone the kidneys secrete in response to hypoxia; EPO travels to the bone marrow and stimulates the production of erythrocytes (red blood cells), which raises the blood''s oxygen-carrying capacity and delivery to tissues. (Choice B) is correct: the kidneys sense the reduced arterial oxygen content and release EPO, which acts on the bone marrow to increase erythrocyte output, the appropriate adaptation to chronic hypoxia at altitude. (Choice A) is incorrect: raising red blood cell production is the right adaptive effect, but the liver is the wrong source. The liver''s endocrine products are insulin-like growth factor-1, angiotensinogen, thrombopoietin, and hepcidin; none of these increase erythrocytes, and it is the kidney, not the liver, that secretes the hormone responsible for red blood cell production in response to low oxygen. (Choice C) is incorrect: aldosterone from the adrenal cortex increases sodium reabsorption and thus blood volume as part of the renin-angiotensin-aldosterone system, a response to low blood pressure, low sodium, or low volume rather than to low oxygen, and it does not increase red blood cell number. (Choice D) is incorrect: the thyroid hormones T3 and T4 raise the basal metabolic rate, which would increase oxygen consumption rather than correct a shortfall in oxygen delivery, and they are not secreted in response to hypoxia. Answering requires applying the oxygen-sensing endocrine pathway to a novel altitude scenario and identifying both the correct source organ and the specific blood cell affected, distinguishing the kidney from another organ paired with the same adaptive effect and from hormones that raise a different blood variable (Skill 2).', 'medium', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 75, NULL)
  RETURNING id
)
