-- Q19 [Gonads, Pineal & Other Tissues] hard skill2 ans=C
WITH q AS (
  INSERT INTO questions (section, topic, subtopic, question_text, options, correct_answer, explanation, difficulty, foundation, content_category, discipline, cognitive_skill, estimated_time_seconds, figure_svg)
  VALUES ('bio_biochem', 'The Endocrine System', 'Gonads, Pineal & Other Tissues', 'A lowlander relocates to a settlement 4,000 m above sea level, where the partial pressure of inspired oxygen is markedly reduced. Over the following weeks, a blood panel shows a steadily climbing hematocrit and erythrocyte count. Which structure is the endocrine source of the signal that drives this adaptation?', '[{"label": "A", "text": "Hepatocytes of the liver"}, {"label": "B", "text": "Red bone marrow"}, {"label": "C", "text": "Interstitial cells of the kidney"}, {"label": "D", "text": "Cortex of the adrenal gland"}]'::jsonb, 'C', 'This is a Biology question that falls under the content category ''Endocrine System: Hormones and Their Sources.'' The answer is C because sustained hypoxia at altitude is detected by the interstitial fibroblast cells of the kidney, which respond by secreting the glycoprotein hormone erythropoietin (EPO); circulating EPO then travels to the red bone marrow and stimulates erythropoiesis, raising the erythrocyte count and hematocrit over a span of weeks. (Choice C) is correct: the kidney is the low-oxygen-sensing endocrine organ, and its interstitial cells are the documented cellular source of EPO released in response to reduced oxygen levels. (Choice B) is incorrect: the red bone marrow is the target tissue where erythrocytes are produced, not the endocrine source of the hormone that initiates the response; marrow makes cells, but it does not secrete the hypoxia-triggered signal that commands their production. (Choice A) is incorrect: the liver is a genuine endocrine organ, but the blood-cell hormone it secretes is thrombopoietin, which drives platelet (not erythrocyte) production, and its other secretions such as insulin-like growth factor-1 and angiotensinogen are unrelated to the oxygen-driven rise in red cells. (Choice D) is incorrect: the adrenal cortex secretes aldosterone and cortisol in response to signals such as low blood volume, angiotensin II, and ACTH rather than to low inspired oxygen, so it is not the sensor that couples hypoxia to increased erythropoiesis. Answering requires tracing a multi-step causal chain—hypoxia to renal hormone secretion to marrow erythropoiesis—and distinguishing the endocrine source from the target tissue, a Skill 2 application of how a specific hormone''s tissue of origin is linked to its physiological stimulus and effect.', 'hard', '3A', 'Endocrine System: Hormones and Their Sources', 'biology', 2, 100, NULL)
  RETURNING id
)
